pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner = address(0xA11CE);

    function setUp() public {
        c = new C();
        vm.deal(address(this), 1e30);
        vm.deal(owner, 1e30);
    }

    function testFuzz_property(uint256 amount, uint256 burn) public {
        amount = bound(amount, 1, address(this).balance);
        burn = bound(burn, 0, 5000);
        vm.deal(address(c), amount);
        GasBurner g = new GasBurner();
        g.setBurn(burn);
        vm.prank(owner);
        bool ok;
        try c.sendTo(address(g), amount) { ok = true; } catch { ok = false; }
