    uint256 b;
    function setBurn(uint256 x) public { b = x; }
    receive() external payable {
        assembly {
            let i := 0
            for { } lt(i, 5000) { i := add(i, 1) } {
                pop(mul(7, 13))
            }
        }
    }
}

