pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 balRaw, uint256 amountRaw, address receiver) public {
        vm.assume(receiver.code.length == 0); // plain EOA receiver: never refuses ether

        // give c a fuzzed, strictly positive balance
        uint256 bal = bound(balRaw, 1, type(uint256).max / 4);
        vm.deal(address(c), bal);

        // fuzz an amount strictly greater than c's balance -> any send must fail
        uint256 amount = bound(amountRaw, bal + 1, type(uint256).max / 2);

        address owner = msg.sender;
        vm.prank(owner);
        bool ok;
        try c.sendTo(receiver, amount) { ok = true; } catch { ok = false; }

        // rule: sending more than the balance must revert; the mutant's
        // unchecked call makes sendTo succeed while sending nothing.
        assertTrue(!ok, "sendTo must revert when amount exceeds contract balance");
    }
}

