pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        // fund the contract so a wide range of amounts is admissible
        vm.deal(address(this), 1000 ether);
        (bool s, ) = address(c).call{value: 100 ether}("");
        assertTrue(s);
        // wide domain: any nonzero amount up to (and beyond) the balance, any receiver
        amount = bound(amount, 1, 200 ether);

        // adversarial counterparty: a callee that refuses Ether.
        // In P, transfer bubbles up its revert -> sendTo reverts (ok == false).
        // In M, the unchecked low-level call swallows the failure -> sendTo returns
        // normally (ok == true) WITHOUT moving any Ether.
        Reverter r = new Reverter();
        address to = receiver == address(0) ? address(r) : receiver;

        uint256 before = address(c).balance;
        bool ok;
        vm.prank(address(this)); // owner drives sendTo
        try c.sendTo(to, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: a non-reverting sendTo must have actually transferred
        // exactly `amount` Wei out of the contract.
        assertTrue(!ok || address(c).balance == before - amount);
    }
}

