import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;

    function setUp() public {
        c = new C();
        owner = address(this); // test contract deployed c, so it is the owner
        vm.deal(owner, 1_000_000 ether);
    }

    function testFuzz_property(address receiver, uint256 amount) public {
