pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Probe probe;

    function setUp() public {
        c = new C();
        probe = new Probe();
    }

    function testFuzz_property(address actor, uint96 amount) public {
        // admissible domain: anyone but the owner may try, any amount, c funded
        vm.assume(actor != address(0));
        vm.assume(actor != c.owner());
        vm.assume(actor != address(probe));
        vm.assume(actor != address(c));
        vm.deal(address(c), 1 ether);
        vm.deal(actor, 1);

        vm.prank(actor);
        bool ok;
        try c.sendTo(address(probe), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: from a NON-owner caller, sendTo reverts BEFORE the
        // receiver is ever invoked, so no transfer to the receiver is ever
        // attempted/executed. The probe's counter witnesses whether c's
        // transfer actually reached the receiver during the call (it survives
        // the revert). Reference C: counter is always 0. Mutant M (transfer
        // before require): the non-owner's transfer executes and increments
        // the counter even though the outer call reverts.
        assertTrue(probe.hits() == 0 || ok, "non-owner call must never reach the receiver");
    }
}

// Adversarial probe receiver: records that it received a transfer from c.
// Its state persists even when the enclosing call reverts, exposing that the
// mutant performs the transfer before its owner check.
contract Probe {
    uint256 public hits;

    receive() external payable {
        hits++;
    }
}

