contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(this)); // exercise the non-owner domain; owner path reverts too
        Reverter r = new Reverter();
        vm.deal(address(c), amount);
        bool ok;
        bytes memory reason;
        vm.prank(actor);
        try c.sendTo(address(r), amount) {
            ok = true;
        } catch (bytes memory data) {
            ok = false;
            reason = data;
        }
        // General rule: any revert of sendTo carries EMPTY revert data (a bare require).
        // Reference: non-owner -> require fails first -> revert(0,0), empty data. Holds for ALL inputs.
        // Mutant: non-owner -> transfer to Reverter executes first -> revert data is the
        // receiver's custom error (4 bytes), so for some input the rule breaks.
        assertTrue(ok || reason.length == 0);
    }
}

