pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address receiver, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(receiver != address(0) && receiver != address(c) && receiver != address(this));
        amount = bound(amount, 0, 5 ether);

        // fund the contract so a transfer is always admissible for the owner path
        vm.deal(address(c), 10 ether);

        uint256 receiverBefore = receiver.balance;

        // drive c through sendTo; the call may succeed or revert, that is part of the rule
        vm.prank(actor);
        try c.sendTo(receiver, amount) {
            // success path: only the owner can succeed; balance delivered is fine
        } catch {
            // revert path
        }

        // General rule: sendTo credits the receiver IF AND ONLY IF the call succeeds.
        // Reference: a non-owner's call reverts BEFORE any transfer, so the receiver
        //             balance never changes; an owner's call succeeds and credits exactly amount.
        // Mutant:     a non-owner's call transfers FIRST and reverts after, so the receiver
        //             is permanently credited even though the call reverted.
        if (actor == c.owner()) {
            assertEq(receiver.balance, receiverBefore + amount);
        } else {
            assertEq(receiver.balance, receiverBefore);
        }
    }
}

